with with_window as (select s.*, sub.id as subscription_id, sub.plan, sub.monthly_fee from sessions s left join subscriptions sub on s.customer_id = sub.customer_id and s.started_at >= sub.start_date and s.started_at <= date_add(sub.end_date, 10)), eligible as (select s.* from with_window s where not exists (select 1 from web_events ch where ch.session_id = s.id and ch.event_time >= s.started_at)), not_flagged as (select s.* from eligible s where not exists (select 1 from web_events x where x.session_id = s.id and x.event_time >= s.started_at)), flagged as (select *, case when started_at - lag(started_at) over (partition by country order by started_at, id, subscription_id) > interval '60' day then 1 else 0 end as is_new_session from not_flagged), sessions_sessions as (select *, sum(is_new_session) over (partition by country order by started_at, id, subscription_id rows between unbounded preceding and current row) as island_id from flagged), metrics as (select *, avg(subscription_id) over (partition by browser, plan order by island_id, id, subscription_id rows between 2 preceding and 1 preceding) as subscription_id_avg_2_prior, sum(island_id) over (partition by country order by is_new_session, id, subscription_id rows between unbounded preceding and current row) as running_island_id from sessions_sessions), not_flagged_sessions as (select s.* from metrics s where exists (select 1 from web_events x where x.session_id = s.id and x.event_time <= s.started_at)), scored as (select id, customer_id, device, browser, started_at, country, subscription_id, plan, monthly_fee, is_new_session, island_id, subscription_id_avg_2_prior, running_island_id, max(running_island_id) over (partition by country) as country_max_running_island_id, ntile(3) over (order by subscription_id_avg_2_prior, id, subscription_id) as subscription_id_avg_2_prior_bucket from not_flagged_sessions) select id, device, country, subscription_id, plan, monthly_fee, is_new_session, running_island_id, subscription_id_avg_2_prior_bucket, case when plan rlike '^(standard|basic)$' then 'OTHER_ZONE' else 'GROUP_A' end as plan_zone from scored;
